CREATE TABLE user_blocks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,blocker_user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,blocked_user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uq_user_block UNIQUE(blocker_user_id,blocked_user_id),CONSTRAINT chk_user_block_self CHECK(blocker_user_id<>blocked_user_id));
CREATE INDEX idx_user_blocks_blocked ON user_blocks(blocked_user_id,blocker_user_id);
